-- Name: equipment_booking_conflict_exists(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.equipment_booking_conflict_exists(p_listing_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
                    SELECT EXISTS (
                        SELECT 1
                        FROM equipment_bookings
                        WHERE listing_id = p_listing_id
                          AND status IN ('pending', 'approved')
                          AND (
                              p_start < (end_datetime + interval '1 hour')
                              AND p_end > start_datetime
                          )
                        LIMIT 1
                    );
                $$;


ALTER FUNCTION public.equipment_booking_conflict_exists(p_listing_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

